class Solution {
public:
    int countSubMultisets(vector<int>& nums, int l, int r) {
        const long long MOD = 1e9 + 7;
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        vector<long long> dp(r + 1, 0);
        dp[0] = 1;
        for (auto& [v, c] : cnt) {
            vector<long long> ndp(r + 1, 0);
            for (int s = 0; s <= r; s++) {
                long long tot = 0;
                for (long long j = 0; j <= c && s - j * v >= 0; j++)
                    tot += dp[s - j * v];
                ndp[s] = tot % MOD;
            }
            dp = move(ndp);
        }
        long long ans = 0;
        for (int s = l; s <= r; s++) ans = (ans + dp[s]) % MOD;
        return ans;
    }
};

