class Solution {
public:
    int countSubMultisets(vector<int>& nums, int l, int r) {
        const long long MOD = 1e9 + 7;
        unordered_map<int,long long> cnt;
        for (int x : nums) cnt[x]++;
        vector<long long> dp(r + 1, 0);
        dp[0] = 1;
        for (auto& [v, c] : cnt) {
            if (v == 0) {
                for (auto& x : dp) x = x * (c + 1) % MOD;
                continue;
            }
            auto ndp = dp;
            for (int rem = 0; rem < min(v, r + 1); rem++) {
                long long acc = 0;
                deque<long long> win;
                for (int s = rem; s <= r; s += v) {
                    acc += dp[s];
                    win.push_back(dp[s]);
                    if ((int)win.size() > c + 1) { acc -= win.front(); win.pop_front(); }
                    ndp[s] = ((acc % MOD) + MOD) % MOD;
                }
            }
            dp = move(ndp);
        }
        long long ans = 0;
        for (int s = l; s <= r; s++) ans = (ans + dp[s]) % MOD;
        return ans;
    }
};

