class Solution {
    public int countSubMultisets(int[] nums, int l, int r) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Long> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1L, Long::sum);
        long[] dp = new long[r + 1];
        dp[0] = 1;
        for (var e : cnt.entrySet()) {
            int v = e.getKey();
            long c = e.getValue();
            if (v == 0) {
                for (int i = 0; i <= r; i++) dp[i] = dp[i] * (c + 1) % MOD;
                continue;
            }
            long[] ndp = dp.clone();
            for (int rem = 0; rem < Math.min(v, r + 1); rem++) {
                long acc = 0;
                ArrayDeque<Long> win = new ArrayDeque<>();
                for (int s = rem; s <= r; s += v) {
                    acc += dp[s];
                    win.addLast(dp[s]);
                    if (win.size() > c + 1) acc -= win.pollFirst();
                    ndp[s] = ((acc % MOD) + MOD) % MOD;
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int s = l; s <= r; s++) ans = (ans + dp[s]) % MOD;
        return (int) ans;
    }
}

